{
  "implementation": "def solve(case):
    nodes = case['nodes']
    required = set(case['required_symbols'])
    node_map = {n['id']: n for n in nodes}
    children = {}
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children.setdefault(pid, []).append(n['id'])

    def descendants(nid):
        stack = [nid]
        visited = set()
        while stack:
            cur = stack.pop()
            if cur in visited:
                continue
            visited.add(cur)
            for ch in children.get(cur, []):
                stack.append(ch)
        return visited

    removed = set()
    removal_order = []
    sorted_ids = sorted(node_map.keys(), key=lambda x: (-node_map[x]['depth'], x))

    for nid in sorted_ids:
        node = node_map[nid]
        if nid == 'root' or not node['removable']:
            continue
        # cannot remove if any child is still retained
        child_ids = children.get(nid, [])
        if any(cid not in removed for cid in child_ids):
            continue
        desc = descendants(nid)
        temp_removed = removed.union(desc)
        # check required symbols after removal
        ok = True
        for sym in required:
            found = False
            for n2 in node_map.values():
                if n2['id'] not in temp_removed and n2['symbol'] == sym:
                    found = True
                    break
            if not found:
                ok = False
                break
        if ok:
            removed.update(desc)
            removal_order.append(nid)

    retained = sorted([nid for nid in node_map if nid not in removed])
    return {"removed_node_ids": removal_order, "retained_node_ids": retained}"
}
